import numpy as np
from scipy import stats
from sklearn.cluster import AgglomerativeClustering

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers using t-statistics
    t_stats = np.array([stats.ttest_ind(feats.x[feats.y==1, feats.column(fid)], 
                                       feats.x[feats.y==0, feats.column(fid)], 
                                       equal_var=False)[0] 
                       for fid in feats.ids])

    # Select top features by absolute t-statistic
    top_indices = np.argsort(np.abs(t_stats))[::-1][:20]
    top_features = [feats.ids[i] for i in top_indices]

    # Check for correlated pairs and remove near-duplicates
    corr_pairs = []
    if len(top_features) > 1:
        X_subset = feats.x[:, [feats.column(fid) for fid in top_features]]
        corr_matrix = np.corrcoef(X_subset.T)
        for i in range(len(top_features)):
            for j in range(i+1, len(top_features)):
                if abs(corr_matrix[i,j]) >= 0.6:
                    corr_pairs.append((top_features[i], top_features[j]))

    # Remove one feature from each highly correlated pair
    to_remove = set()
    for a, b in corr_pairs:
        if a in to_remove or b in to_remove:
            continue
        # Prefer the one with higher t-statistic
        try:
            idx_a = top_features.index(a)
            idx_b = top_features.index(b)
            if abs(t_stats[idx_a]) > abs(t_stats[idx_b]):
                to_remove.add(b)
            else:
                to_remove.add(a)
        except ValueError:
            # Skip if feature not found (shouldn't happen but just in case)
            continue

    # Build final driver list
    drivers = [fid for fid in top_features if fid not in to_remove][:MAX_DRIVERS]

    # If no mechanism found, return empty design
    if not drivers:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # For module-based approach, cluster features with high correlation
    X_subset = feats.x[:, [feats.column(fid) for fid in drivers]]
    if len(drivers) > 1:
        # Use hierarchical clustering to group correlated features
        try:
            clustering = AgglomerativeClustering(n_clusters=min(3, len(drivers)), 
                                               linkage='ward', 
                                               affinity='euclidean')
            clusters = clustering.fit_predict(X_subset)

            # Find best cluster (highest average t-statistic)
            cluster_means = []
            for c in set(clusters):
                cluster_mean = np.mean([t_stats[feats.column(fid)] 
                                      for i, fid in enumerate(drivers) if clusters[i] == c])
                cluster_means.append(cluster_mean)

            best_cluster_idx = np.argmax(cluster_means)

            # Select features in best cluster
            module_features = [drivers[i] for i in range(len(drivers)) if clusters[i] == best_cluster_idx]

            # Create weighted score from module features
            weights = np.array([abs(t_stats[feats.column(fid)]) for fid in module_features])
            weights = weights / np.sum(weights)  # Normalize

            # Return design with module features and their loadings
            return Design(
                drivers=tuple(module_features),
                columns=tuple(module_features),
                products=(),
                loadings={fid: float(w) for fid, w in zip(module_features, weights)}
            )
        except:
            # Fallback to simple approach if clustering fails
            pass

    # Single driver case or fallback
    return Design(
        drivers=tuple(drivers),
        columns=tuple(drivers),
        products=(),
        loadings={drivers[0]: 1.0}
    )
